def parse_duration(s: str) -> int:
    if not s:
        raise ValueError()

    total = 0
    i = 0
    n = len(s)

    while i < n:
        j = i
        while j < n and s[j].isdigit():
            j += 1

        if j == i:
            raise ValueError()

        num = int(s[i:j])
        i = j

        if i >= n:
            raise ValueError()

        unit = s[i]
        i += 1

        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
        else:
            raise ValueError()

    return total
